package com.gymmind.nutrition.application; import com.gymmind.audit.application.AuditRecorder; import com.gymmind.audit.domain.*; import com.gymmind.iam.domain.model.RoleCode; import com.gymmind.nutrition.domain.model.NutritionFood; import com.gymmind.nutrition.domain.repository.NutritionFoodRepository; import com.gymmind.shared.error.*; import com.gymmind.shared.security.CurrentActor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.Map;
@Service public class DefaultNutritionFoodService implements NutritionFoodService { final NutritionFoodRepository foods; final AuditRecorder audit; public DefaultNutritionFoodService(NutritionFoodRepository f,AuditRecorder a){foods=f;audit=a;} @Transactional public NutritionFoodView create(CurrentActor actor,CreateNutritionFoodCommand c){if(actor==null||actor.tenantId()==null||!actor.roles().contains(RoleCode.GYM_ADMIN)||!actor.hasPermission("nutrition:write"))throw new BusinessException(ErrorCode.FORBIDDEN);if(c==null||c.tenantId()!=null&&!actor.tenantId().equals(c.tenantId())||c.name()==null||c.name().isBlank()||c.servingSize()==null||c.servingSize().isBlank()||c.calories()<0||c.protein()<0||c.carbohydrate()<0||c.fat()<0)throw new BusinessException(ErrorCode.VALIDATION_FAILED);NutritionFood f=foods.save(NutritionFood.create(actor.tenantId(),c.name(),c.calories(),c.protein(),c.carbohydrate(),c.fat(),c.servingSize()));audit.record(new AuditEvent("NUTRITION_FOOD_CREATED","NUTRITION_FOOD",f.getId(),AuditResult.SUCCESS,"nutrition-food-service",Map.of("resourceName",f.getName())));return NutritionFoodView.from(f);} }
